<map version="1.0.1"><node CREATED="1747229372253" ID="ID_root" MODIFIED="1747229372253" TEXT="算法"><node CREATED="1747229372253" ID="ID_83c3f014213625e4" POSITION="right" MODIFIED="1747229372253" TEXT="算法的学习重心"><node CREATED="1747229372253" ID="ID_e6a160931a3506ce" MODIFIED="1747229372253" TEXT="一定要注意算法的思路"></node><node CREATED="1747229372253" ID="ID_0642ba79f37c748e" MODIFIED="1747229372253" TEXT="进公司了之后，基本很少碰到排序的题目。&amp;nbsp;或者说代码。&amp;nbsp;&amp;lt;br&amp;gt;即使碰到了，网上搜，复制粘贴过来"></node><node CREATED="1747229372253" ID="ID_48c88af50801fa22" MODIFIED="1747229372253" TEXT="面试的时候经常问到"><node CREATED="1747229372253" ID="ID_9529e5ae201ca9c6" MODIFIED="1747229372253" TEXT="比如，简单聊聊插入排序"></node><node CREATED="1747229372253" ID="ID_fa22989ab0e705b1" MODIFIED="1747229372253" TEXT="要注意的点，能够用自己的话把算法的核心思想表示出来。&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_f70f43beab530ab0" MODIFIED="1747229372253" TEXT="对于一些常见的算法，要能够手写出来。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_9d05240f740537d4" MODIFIED="1747229372253" TEXT="现在先学思想。&amp;nbsp;然后代码敲两遍，等到面试之前的几天，每天背一遍。&amp;lt;br&amp;gt;这些东西，面试的时候也能写出来"></node></node></node><node CREATED="1747229372253" ID="ID_04b066bc44844fc3" MODIFIED="1747229372253" TEXT="要能够评估一个算法的时间复杂度和空间复杂度"><node CREATED="1747229372253" ID="ID_3a46bf41bcec5187" MODIFIED="1747229372253" TEXT="时间复杂度就是花费了多少时间.&amp;lt;br&amp;gt;关心一些操作的量级"><node CREATED="1747229372253" ID="ID_6aa3eb1814d9e81d" MODIFIED="1747229372253" TEXT="O(n)"></node><node CREATED="1747229372253" ID="ID_afcb8808fb6eb7a2" MODIFIED="1747229372253" TEXT="只关心量级，不关心具体的&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_00bfc172ba711b07" MODIFIED="1747229372253" TEXT="比如，对于一个数组的查找指定下标。&amp;nbsp;&amp;lt;br&amp;gt;算index=i的数据。&amp;nbsp;&amp;lt;br&amp;gt;base_addr + i * sizeof(int)"><node CREATED="1747229372253" ID="ID_33298276fabf0b1e" MODIFIED="1747229372253" TEXT="O(1)：&amp;nbsp;和数据的规模无关。&amp;nbsp;&amp;lt;br&amp;gt;O(10)"></node><node CREATED="1747229372253" ID="ID_ccc8aa8d7f2aa8bd" MODIFIED="1747229372253" TEXT="对于一个链表，也要取index=i的数据。&amp;nbsp;&amp;lt;br&amp;gt;数据访问就和数据的长度是相关的。&amp;nbsp;&amp;lt;br&amp;gt;O(n)"></node><node CREATED="1747229372253" ID="ID_2f435567692230be" MODIFIED="1747229372253" TEXT="O(n^2)、O(n^3):&amp;nbsp;写代码的时候，不要使劲套循环。&amp;lt;br&amp;gt;&amp;nbsp;如果使劲套循环，想一下更简单的方式：&amp;nbsp;基本都是可以使用哈希表做简化的"></node><node CREATED="1747229372253" ID="ID_b5fa45bedf7e42ce" MODIFIED="1747229372253" TEXT="也要注意一下，一些代码的单行时间复杂度。&amp;nbsp;&amp;lt;br&amp;gt;linkedlist_get_index(list, index);"></node></node></node><node CREATED="1747229372253" ID="ID_871980501daed6de" MODIFIED="1747229372253" TEXT="空间复杂度：&amp;nbsp;这个算法占用了多少空间"><node CREATED="1747229372253" ID="ID_1b37164f23b84a94" MODIFIED="1747229372253" TEXT="O(1)&amp;lt;br&amp;gt;O(n)"></node></node><node CREATED="1747229372253" ID="ID_1f61b5e00c034b59" MODIFIED="1747229372253" TEXT="trade off"><node CREATED="1747229372253" ID="ID_50c6ca5c196e25b0" MODIFIED="1747229372253" TEXT="时间换空间；&amp;nbsp;空间换时间"></node></node><node CREATED="1747229372253" ID="ID_2b71bd009dfa1267" MODIFIED="1747229372253" TEXT="稳定性：&amp;nbsp;排序算法的稳定性。&amp;lt;br&amp;gt;&amp;nbsp;对于相同的数据，排序前后的顺序是否相同"><node CREATED="1747229372253" ID="ID_3879c18cd19c39f9" MODIFIED="1747229372253" TEXT="9&amp;nbsp; &amp;nbsp;8&amp;apos;&amp;nbsp; 1&amp;apos;&amp;nbsp; &amp;nbsp; &amp;nbsp;3&amp;nbsp; &amp;nbsp;1&amp;apos;&amp;apos;&amp;nbsp; &amp;nbsp; 6&amp;nbsp; &amp;nbsp;8&amp;apos;&amp;apos;&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_c8790823d43b43c5" MODIFIED="1747229372253" TEXT="1&amp;apos; 1&amp;apos;&amp;apos; 3 6 8&amp;apos; 8&amp;apos;&amp;apos; 9"></node><node CREATED="1747229372253" ID="ID_ff7eadcda0fe5503" MODIFIED="1747229372253" TEXT="现在排序的是基本的数据结构。&amp;nbsp;后续如果排序的是结构体，&amp;lt;br&amp;gt;&amp;nbsp;比如是按照结构体里面的年龄排序，&amp;lt;br&amp;gt;对于结构体的数据是有区别的。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229372253" ID="ID_0a75420030ddec65" MODIFIED="1747229372253" TEXT="在学习排序算法的时候，&amp;nbsp;我们是以基本数据类型int举例。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_f1fa6d4e4447ffea" MODIFIED="1747229372253" TEXT="qsort()"><node CREATED="1747229372253" ID="ID_761bfac6934c7b95" MODIFIED="1747229372253" TEXT="函数指针，大小关系。"></node></node><node CREATED="1747229372253" ID="ID_717b3c2cc7a4d742" MODIFIED="1747229372253" TEXT="后续只要学会了这个排序思想，&amp;nbsp;排其他类型是一样的。&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_df0e626ba2dade41" MODIFIED="1747229372253" TEXT="冒泡算法的实现要能写出来"></node></node></node><node CREATED="1747229372253" ID="ID_486a731dbce5b45e" POSITION="right" MODIFIED="1747229372253" TEXT="排序算法"><node CREATED="1747229372253" ID="ID_55ff09c8e62e0c07" MODIFIED="1747229372253" TEXT="基本排序"><node CREATED="1747229372253" ID="ID_f33b8e923f3e7ea1" MODIFIED="1747229372253" TEXT="选择排序"><node CREATED="1747229372253" ID="ID_9505bb25621ccdb1" MODIFIED="1747229372253" TEXT="每一轮将最小的/最大的，选到最前面，或者最后面。&amp;nbsp;重复选择，选择结束，数据就有序了"></node></node><node CREATED="1747229372253" ID="ID_d4f6ceec5cdf8712" MODIFIED="1747229372253" TEXT="冒泡排序"><node CREATED="1747229372253" ID="ID_b159bc2a7dfa3911" MODIFIED="1747229372253" TEXT="每一轮，都比较相邻的两个数据，如果前面的数据大，后面的数据小，就调换两者位置。&amp;nbsp;继续处理下一对。&amp;nbsp;&amp;lt;br&amp;gt;一轮循环结束，最大的就到了后面。&amp;nbsp;"></node></node><node CREATED="1747229372253" ID="ID_90c167cc4093fc81" MODIFIED="1747229372253" TEXT="插入排序"><node CREATED="1747229372253" ID="ID_2025746d875852f8" MODIFIED="1747229372253" TEXT="就是先认为第一个数据有序。然后将后面的数据插入到正确的位置。&amp;nbsp;"></node></node></node><node CREATED="1747229372253" ID="ID_10297571897f001c" MODIFIED="1747229372253" TEXT="高级排序"><node CREATED="1747229372253" ID="ID_fb2cd42263a2fe8a" MODIFIED="1747229372253" TEXT="希尔排序"><node CREATED="1747229372253" ID="ID_0c8e10702afe8869" MODIFIED="1747229372253" TEXT="时间复杂度 O(n^2)。稍有改进，但最坏还是O(n^2)"></node><node CREATED="1747229372253" ID="ID_f8ccd5f53942122c" MODIFIED="1747229372253" TEXT="空间复杂度O(1)"></node><node CREATED="1747229372253" ID="ID_7a9b884467cdae2b" MODIFIED="1747229372253" TEXT="稳定性：不稳定"></node></node><node CREATED="1747229372253" ID="ID_c407ce312fa698af" MODIFIED="1747229372253" TEXT="归并排序"><node CREATED="1747229372253" ID="ID_92d407d74313ae58" MODIFIED="1747229372253" TEXT="分治思想。&amp;nbsp;将数组先一直拆。"></node><node CREATED="1747229372253" ID="ID_c3032f2d8270bd65" MODIFIED="1747229372253" TEXT="时间复杂度O(nlogn)"></node><node CREATED="1747229372253" ID="ID_8d0a7d39bf83a61a" MODIFIED="1747229372253" TEXT="空间复杂度O(n)"></node><node CREATED="1747229372253" ID="ID_728c1f2659648b58" MODIFIED="1747229372253" TEXT="稳定性：稳定的&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229372253" ID="ID_4cf105de4a97d3cd" MODIFIED="1747229372253" TEXT="快排"><node CREATED="1747229372253" ID="ID_644ae03309b9689a" MODIFIED="1747229372253" TEXT="快排的思想，就是找一个中枢，比中枢小的都放在左边，比中枢大的都放在右边。&amp;nbsp;&amp;lt;br&amp;gt;继续处理中枢左边的子数组，和右边的子数组。&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_90598c677631e4a6" MODIFIED="1747229372253" TEXT="快排就是找中枢，然后将比中枢小的放左边，比中枢大的放右边。"></node><node CREATED="1747229372253" ID="ID_76842c1b1c3d4557" MODIFIED="1747229372253" TEXT="时间复杂度： O(nlog(n))"></node><node CREATED="1747229372253" ID="ID_cf31694029688af9" MODIFIED="1747229372253" TEXT="空间复杂度：O(logn)"></node><node CREATED="1747229372253" ID="ID_a902139d278b396f" MODIFIED="1747229372253" TEXT="稳定性：不稳定"></node><node CREATED="1747229372253" ID="ID_d51f44ecfcf2159f" MODIFIED="1747229372253" TEXT="思想和代码都要能写出来&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229372253" ID="ID_953997bb7b55a5b3" MODIFIED="1747229372253" TEXT="堆排"><node CREATED="1747229372253" ID="ID_3f7307f693d5d975" MODIFIED="1747229372253" TEXT="时间复杂度 O(nlogn)"></node><node CREATED="1747229372253" ID="ID_91238fcbe7ebdb5d" MODIFIED="1747229372253" TEXT="空间复杂复 O(1)"></node><node CREATED="1747229372253" ID="ID_3b643f18e4a4d765" MODIFIED="1747229372253" TEXT="稳定性：&amp;nbsp;不稳定"></node></node></node></node><node CREATED="1747229372253" ID="ID_989e84d06478b0cf" POSITION="right" MODIFIED="1747229372253" TEXT="归并排序、快排、堆排。&amp;lt;br&amp;gt;大数据场景下的应用场景"><node CREATED="1747229372253" ID="ID_3804b494905c9166" MODIFIED="1747229372253" TEXT="归并排序的变种：&amp;nbsp;利用文件来排序非常非常大的数据"><node CREATED="1747229372253" ID="ID_84b966c628dca46d" MODIFIED="1747229372253" TEXT="比如，现在有100T的文件，需要排个序。&amp;nbsp;一定要听清楚前提：&amp;nbsp;非常非常非常大。&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_7c8a719aaf29ea27" MODIFIED="1747229372253" TEXT="面试官的话里如果给你强调了数据很大，这时候传统的排序算法，很难发挥作用"></node><node CREATED="1747229372253" ID="ID_922c40b27184cca6" MODIFIED="1747229372253" TEXT="归并的文件中合并方式。&amp;nbsp;&amp;lt;br&amp;gt;归并排序，可以将数据放在文件中。&amp;lt;br&amp;gt;拆成10w个文件。&amp;nbsp; &amp;nbsp;&amp;lt;br&amp;gt;100 * 1000&amp;nbsp; / 100000 = 1000m&amp;lt;br&amp;gt;对单个文件进行排序。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_619defc2998b649a" MODIFIED="1747229372253" TEXT="变种的归并排序。&amp;nbsp;"></node></node><node CREATED="1747229372253" ID="ID_ff4f80c0fb5c39af" MODIFIED="1747229372253" TEXT="下次面试官刻意强调很大很大。这时候，传统的排序算法搞不定。&amp;lt;br&amp;gt;可以用归并排序。文件完成辅助归并。&amp;nbsp;&amp;lt;br&amp;gt;首先，先把大文件拆分成小文件，比如拆成1G大小的文件。&amp;nbsp;&amp;lt;br&amp;gt;其次，对这每一个小文件，分别内部排序。&amp;nbsp;每个文件里都是有序的。&amp;nbsp;&amp;lt;br&amp;gt;再从这1w个文件中，一个一个拿出最小的。只要将所有的数据都拿完，100T文件有序了。"></node></node><node CREATED="1747229372253" ID="ID_02cfd48c8d1cd515" MODIFIED="1747229372253" TEXT="topN问题：&amp;nbsp;有1000w条数据，找前200个最大的。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_918def6352287c79" MODIFIED="1747229372253" TEXT="比较笨的方式：就是将数据整个排序。&amp;nbsp;排完序之后，取最后200个，就是200个最大的。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_6dfbc3d61f127e23" MODIFIED="1747229372253" TEXT="这个需要花费长度为1000w的数据。&amp;nbsp;"></node></node><node CREATED="1747229372253" ID="ID_af58c48d8bee5645" MODIFIED="1747229372253" TEXT="堆排。&amp;nbsp;"><node CREATED="1747229372253" ID="ID_8e82e9fd7b7fdd96" MODIFIED="1747229372253" TEXT="先建大顶堆。&amp;nbsp;然后摘根节点。然后将最后的换到前面来。&amp;nbsp;这样重复200次，"></node><node CREATED="1747229372253" ID="ID_56eb74db900b46b5" MODIFIED="1747229372253" TEXT="构建一个长度为200的堆。&amp;nbsp;然后将数据拿进来比，符合条件留下，不符合条件丢掉。"></node><node CREATED="1747229372253" ID="ID_55111d48535aa452" MODIFIED="1747229372253" TEXT="构建一个小顶堆，然后小顶堆的根就是最小的。&amp;nbsp;&amp;lt;br&amp;gt;如果来了一个数据，比我们的最小的要大。&amp;nbsp;说明够top200的资格。然后将数据换进来。调整堆。&amp;lt;br&amp;gt;最后我的堆上的数据，留下的就是前200个最大的。&amp;nbsp;"></node><node CREATED="1747229372253" ID="ID_b5f3c76a28062468" MODIFIED="1747229372253" TEXT="大顶堆、小顶堆。"></node></node></node></node></node></map>